metadata.vgl:
vgraph whyAndWhenIbis: IBIS "Why and When IBIS" {
    node qWhen: Question "When should IBIS be used?";
    node aThink: Answer "If you want to think something through";
    node aShared: Answer "For a shared session";
    node conThink: Con "It doesn't provide you with the right questions to ask";
    node proThink: Pro "All questions can be captured";
    node qOver: Question "How to overcome this?";
    node aUseAny: Answer "Use it with any approach that you like. Ask the questions you like.";
    node aUnique: Answer "Every Problem is unique. You cannot know the right questions abfront.";
    node proShared1: Pro "Can easily express the combined input from several people";
    node proShared2: Pro "Easy to add a node during shared sessions";
    node qWhyGood: Question "Why is that good?";
    node aNeutral: Answer "IBIS is neutral to who said what";
    node aBrainstorm: Answer "Great as a result of a brainstorming session";
    node qWhy: Question "Why using IBIS?";
    node aPicture: Answer "A picture is worth a thousand words";
    node aFour: Answer "You can describe any argumentation with the four node types";
    node proStructure: Pro "Structure of argumentation is easy to understand";
    node proLook: Pro "Outcome is reasonable nice to look at";
    node proClear: Pro "These four types facilitate a clear structure";

    edge qWhen -> aThink;
    edge qWhen -> aShared;
    edge aThink -> conThink;
    edge aThink -> proThink;
    edge conThink -> qOver;
    edge qOver -> aUseAny;
    edge qOver -> aUnique;
    edge aShared -> proShared1;
    edge aShared -> proShared2;
    edge proShared1 -> qWhyGood;
    edge qWhyGood -> aNeutral;
    edge qWhyGood -> aBrainstorm;
    edge qWhy -> aPicture;
    edge qWhy -> aFour;
    edge aPicture -> proStructure;
    edge aPicture -> proLook;
    edge aFour -> proClear;
}
